/**
 * The shapes the console pages read. The API's own contract is lib/api/openapi.ts, generated by
 * openapi-typescript 7.13.0 from openapi.json at the repository root; lib/api/adapt.ts turns each
 * answer of that contract into one of these, so a page never reads a field the API does not send
 * and every value here traces to one the API served. Regenerate the contract after an API change:
 *   pnpm dlx openapi-typescript@7.13.0 ../openapi.json -o lib/api/openapi.ts
 * Status values stay strings as the NVD writes them; nothing here assumes the vocabulary.
 */

/** RFC 9457 problem document; every error the API returns is one. */
export type Problem = {
  type: string;
  title: string;
  status: number;
  detail?: string | null;
  instance?: string | null;
};

/** Every answer carries the data version and the statement. */
export type ResponseMeta = { data_version: string; statement: string };

/** A source is stale once its lock is older than its cadence allows (two hours hourly, a day and a half daily). */
export type SourceFreshness = { source: string; fetched_at: string | null; cadence: string; stale: boolean };

export type Health = {
  statement: string;
  status: string;
  /** ok, unreachable or not configured */
  database: string;
  data_version: string;
  version: string;
  /** The serving release loaded, or null before the first sync. */
  release: string | null;
  synced_at: string | null;
  generated_at: string | null;
  storage: { used_bytes: number | null; ceiling_bytes: number; share: number | null };
};

export type Lock = {
  source: string;
  digest: string;
  files: number;
  rows: number;
  fetched_at: string | null;
  cadence: string;
};

export type RunLedgerRow = {
  source: string;
  window: string;
  rows_in: number;
  rows_changed: number;
  digest: string;
  duration_s: number;
  status: string;
  finished_at: string;
  note: string | null;
};

export type QuarantineCount = { rule: string; description: string; rows: number; cves: number | null };

export type BundleFile = { file: string; sha256: string; rows: number | null };

export type Meta = ResponseMeta & {
  version: string;
  nvd_notice: string;
  ghsa_attribution: string;
  repository: string;
  locks: Lock[];
  run_ledger: RunLedgerRow[];
  quarantine: QuarantineCount[];
  bundle: { tag: string; generated_at: string; lake_digest: string; files: BundleFile[] } | null;
  limits: {
    page_size_max: number;
    sbom_upload_max_bytes: number;
    lookups_per_day: number;
    matches_per_day: number;
    storage_ceiling_mb: number;
  } | null;
};

export type Kev = { listed: boolean; date_added: string | null; ransomware: string | null };

/** One served field with who published its value and since when; value null when none was published. */
export type CveField = {
  field: string;
  value: string | number | boolean | string[] | null;
  source: string | null;
  known_from: string | null;
  /** How the value is dated: an event and its rule, the publication, or "not yet known" in an as-of view. */
  dated_by: string;
};

export type Cve = ResponseMeta & {
  id: string;
  state: string | null;
  as_of: string | null;
  /** False in an as-of view before the CVE was published. */
  known: boolean;
  note: string | null;
  published: string | null;
  last_modified: string | null;
  filer: string | null;
  filer_type: string | null;
  nvd_status: string | null;
  nvd_status_since: string | null;
  description: string | null;
  cve_org_url: string;
  nvd_url: string;
  kev: Kev;
  epss: { score: number | null; since: string | null };
  fields: CveField[];
};

export type TimelineKind =
  | "published"
  | "filer_score"
  | "nvd_status"
  | "cisa_adp"
  | "kev_listed"
  | "exploit_code"
  | "ghsa_advisory"
  | "rejected";

export type TimelineEvent = {
  at: string;
  kind: TimelineKind;
  source: string;
  /** The value as the source gave it: a status, a vector, an SSVC decision, a module path. */
  value: string | null;
  /** For nvd_status: whether the status counts as analyzed (Analyzed or Modified, as the lake counts it). */
  analyzed: boolean | null;
};

/** EPSS on a registered day after publication, kept for KEV listed CVEs only. */
export type EpssOffset = { offset_days: number; score: number | null; score_date: string };

export type Timeline = ResponseMeta & {
  id: string;
  now: string;
  published: string | null;
  events: TimelineEvent[];
  epss: EpssOffset[];
};

export type CveSummary = {
  id: string;
  published: string | null;
  last_modified: string | null;
  nvd_status: string | null;
  nvd_status_since: string | null;
  kev_listed: boolean;
  kev_date_added: string | null;
  filer: string | null;
  filer_type: string | null;
  cwe: string[];
  /** The filer's CVSS 4.0 score, else its 3.1 score. */
  filer_cvss: number | null;
  filer_severity: string | null;
  epss: number | null;
};

export type CveList = ResponseMeta & { items: CveSummary[]; next_cursor: string | null };

export type BacklogSeries = {
  key: string;
  label: string;
  /** Slot in the fixed chart palette, 1 to 8. */
  slot: number;
  values: (number | null)[];
};

export type BacklogQuestion = {
  id: string;
  /** The one message of the chart, rendered from the question's values. */
  title: string;
  source: string;
  window: string;
  unit: string;
  kind: "line" | "bar";
  x: string[];
  series: BacklogSeries[];
  rule: { x: string; label: string } | null;
  sql: string;
};

export type Backlog = ResponseMeta & { questions: BacklogQuestion[]; data_cut: string | null };

export type Product = {
  id: string;
  name: string;
  what: string | null;
  ecosystem: string | null;
  kind: string | null;
  stand_in: string;
  repository_url: string | null;
  commit: string | null;
  pinned_on: string | null;
  licence: string | null;
  stars: number | null;
  read_on: string | null;
};

export type ProductList = ResponseMeta & { items: Product[] };

export type Finding = {
  component: string;
  version: string;
  purl: string | null;
  advisory_ids: string[];
  cve_ids: string[];
  matched_range: string | null;
  fixed: string[];
  fix_available: boolean | null;
  source: string;
  advisory_known_from: string | null;
  /** As known on the snapshot day; null when the API did not look the CVE up (an uploaded SBOM). */
  nvd_status: string | null;
  kev_listed: boolean | null;
};

export type Exposure = ResponseMeta & {
  product_id: string;
  as_of: string;
  snapshots: string[];
  findings: Finding[];
  summary: {
    findings: number;
    distinct_cves: number;
    cves_kev_listed: number;
    cves_with_exploit_code: number;
    findings_fix_available: number | null;
    cves_by_nvd_status: Record<string, number>;
  };
};

export type MatchResult = ResponseMeta & {
  sbom_digest: string;
  format: string;
  components: number;
  without_purl: number;
  findings: Finding[];
  duration_ms: number;
  engine: string;
};
